package com.acaivis.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.Date;
@Service public class JwtService {private final SecretKey key; private final long expiration; public JwtService(@Value("${jwt.secret}") String secret,@Value("${jwt.expiration-ms}") long exp){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));expiration=exp;} public String generate(String subject){Date now=new Date();return Jwts.builder().subject(subject).issuedAt(now).expiration(new Date(now.getTime()+expiration)).signWith(key).compact();} public String extractSubject(String token){return parser().parseSignedClaims(token).getPayload().getSubject();} public boolean valid(String token){try{parser().parseSignedClaims(token);return true;}catch(JwtException|IllegalArgumentException e){return false;}} private JwtParser parser(){return Jwts.parser().verifyWith(key).build();}}
